sections=[]
def runs(p,text):
    # Keep English terms together and explicitly left-to-right.
    for part in re.split(r'([A-Za-z0-9]+(?:[ ._+%=/<>:×,\-]+[A-Za-z0-9]+)*)',text):
        if not part: continue
        run=p.add_run(part)
        props=run._element.get_or_add_rPr()
        rtl=OxmlElement('w:rtl'); rtl.set(qn('w:val'),'0' if re.match('[A-Za-z0-9]',part) else '1'); props.append(rtl)
        sz=OxmlElement('w:szCs'); sz.set(qn('w:val'),str(int((run.font.size or p.style.font.size or Pt(11)).pt*2))); props.append(sz)
def para(text,style=None):
    p=doc.add_paragraph(style=style)
    p.alignment=WD_ALIGN_PARAGRAPH.RIGHT
    p._p.get_or_add_pPr().find(qn('w:jc')).set(qn('w:val'),'start')
    bidi=OxmlElement('w:bidi'); p._p.get_or_add_pPr().append(bidi)
    runs(p,text)
    return p
def page(title,texts,figures=(),table=None):
    if sections: doc.add_page_break()
    para(title,'Heading 1' if sections else 'Title')
    for text in texts: para(text)
    if table:
        headers,rows=table
        t=doc.add_table(rows=1, cols=len(headers)); t.style='Table Grid'
        for j,x in enumerate(headers): t.rows[0].cells[j].text=str(x)
        for row in rows:
            cells=t.add_row().cells
            for j,x in enumerate(row): cells[j].text=str(x)
        for i,row in enumerate(t.rows):
            for cell in row.cells:
                for p in cell.paragraphs:
                    p.alignment=WD_ALIGN_PARAGRAPH.CENTER
                    p.paragraph_format.space_after=Pt(3)
                    p.paragraph_format.space_before=Pt(3)
                    p._p.get_or_add_pPr().append(OxmlElement('w:bidi'))
                    for run in p.runs: run.font.name='Tahoma'; run.font.size=Pt(10)
                if i==0:
                    shade=OxmlElement('w:shd');shade.set(qn('w:fill'),'E8EDF2');cell._tc.get_or_add_tcPr().append(shade)
        borders=OxmlElement('w:tblBorders')
        for edge in ['top','left','bottom','right','insideH','insideV']:
            x=OxmlElement('w:'+edge); x.set(qn('w:val'),'single');x.set(qn('w:sz'),'4');x.set(qn('w:color'),'D9D9D9');borders.append(x)
        t._tbl.tblPr.append(borders)
        t.rows[0]._tr.get_or_add_trPr().append(OxmlElement('w:tblHeader'))
    for filename,caption,width in figures:
        p=doc.add_paragraph();p.alignment=WD_ALIGN_PARAGRAPH.CENTER
        p.paragraph_format.space_after=Pt(2)
        p.add_run().add_picture(str(OUT/(filename+'.png')),width=Inches(width))
        para(caption,'Caption')
    sections.append((title,texts,figures,table))

